<?php
/**
 * Check the submission ZIP generated by the real package builder.
 * These artifact checks do not replace installed WordPress acceptance.
 *
 * @package FormidableGeolocationAutocomplete\Tests
 */

$root = dirname( __DIR__ );
$slug = 'logical-address-autocomplete-for-formidable-forms';
$entry = 'logical-address-autocomplete-for-formidable-forms.php';
$output = sys_get_temp_dir() . '/frmgeoac-package-' . bin2hex( random_bytes( 6 ) );
$command = escapeshellarg( PHP_BINARY ) . ' ' . escapeshellarg( $root . '/tools/package/build.php' ) . ' ' . escapeshellarg( $output );
exec( $command . ' 2>&1', $messages, $status );
if ( 0 !== $status ) {
	fwrite( STDERR, implode( PHP_EOL, $messages ) . PHP_EOL );
	exit( 1 );
}
$zip = new ZipArchive();
if ( true !== $zip->open( $messages[0] ) ) {
	throw new RuntimeException( 'Cannot inspect the submission ZIP.' );
}
$prefix = $slug . '/';
$files = [];
for ( $index = 0; $index < $zip->numFiles; ++$index ) {
	$files[] = $zip->getNameIndex( $index );
}
$checks = [];
$checks['one requested-slug root'] = ! array_filter( $files, static function ( $file ) use ( $prefix ) {
	return 0 !== strpos( $file, $prefix );
} );
foreach ( [ 'build.js', 'package.json', 'package-lock.json' ] as $file ) {
	$checks[ 'excludes build metadata: ' . $file ] = ! in_array( $prefix . $file, $files, true );
	$checks[ 'retains source build metadata: ' . $file ] = is_file( $root . '/' . $file );
}
foreach ( [
	$entry, 'readme.txt', 'change_log.txt',
	'src/Features/Form/Fields/Address/Field.php', 'src/Features/Form/Admin/FormEditor.php',
	'assets/js/autocomplete/services/address-autocomplete.js', 'assets/js/editor/form-editor.js',
	'src/Admin/Dashboard/assets/scss/dashboard.scss', 'assets/licenses/choices.txt',
	'build/js/frontend/address-autocomplete.min.js', 'build/js/admin/frmgeo-form-editor.min.js',
	'languages/' . $slug . '.pot',
] as $file ) {
	$checks[ 'includes ' . $file ] = in_array( $prefix . $file, $files, true );
}
for ( $number = 1; $number <= 5; ++$number ) {
	$file = 'assets/screenshots/screenshot-' . $number . '.png';
	$checks[ 'includes ' . $file ] = in_array( $prefix . $file, $files, true );
}
$checks['no development or private directories'] = ! array_filter( $files, static function ( $file ) use ( $prefix ) {
	return preg_match( '#^(?:\.git|\.agents|\.codex|\.vscode|docs|tests|tools|vendor|node_modules|dist)/#', substr( $file, strlen( $prefix ) ) );
} );
$main = $zip->getFromName( $prefix . $entry );
$readme = $zip->getFromName( $prefix . 'readme.txt' );
$checks['Logical public plugin title'] = false !== strpos( $main, 'Plugin Name: Logical Address Autocomplete for Formidable Forms' );
$checks['host-specific internal display name'] = false !== strpos( $main, "define( 'FRMGEOAC_PLUGIN_NAME', 'Address Autocomplete for Formidable Forms' );" );
$checks['entry filename matches requested slug'] = $entry === $slug . '.php';
$checks['requested translation domain'] = false !== strpos( $main, 'Text Domain: ' . $slug );
$checks['host dependency retained'] = false !== strpos( $main, 'Requires Plugins: formidable' );
$checks['unchanged free runtime identity'] = false !== strpos( $main, "define( 'FRMGEOAC_PREFIX', 'frmgeo' );" )
	&& false !== strpos( $main, "define( 'FRMGEOAC_PACKAGE_TYPE', 'free' );" );
$checks['name and contributor in readme'] = 1 === preg_match( '/^=== Logical Address Autocomplete for Formidable Forms ===$/m', $readme )
	&& 1 === preg_match( '/^Contributors: ninjew$/m', $readme );
$checks['version and stable tag agree'] = 1 === preg_match( '/^ \* Version: 1\.0\.0$/m', $main )
	&& 1 === preg_match( '/^Stable tag: 1\.0\.0$/m', $readme );
$checks['tested up to only in readme'] = ! preg_match( '/^ \* Tested up to:/mi', $main ) && 1 === preg_match( '/^Tested up to: /m', $readme );
$checks['simple API requirement and host tutorial'] = false !== strpos( $readme, 'A Google Maps API key is required for address autocomplete to work.' )
	&& false !== strpos( $readme, 'https://formidablegeolocation.com/docs/google-maps-api-keys-formidable-geolocation/' );
$checks['public source and build instructions'] = false !== strpos( $readme, 'https://github.com/Fitoussi/logical-address-autocomplete-for-formidable-forms' )
	&& false !== strpos( $readme, 'npm ci' ) && false !== strpos( $readme, 'npm run build' );
preg_match( '/== Screenshots ==\s*(.*?)\s*== Changelog ==/s', $readme, $screenshots );
$checks['five numbered screenshot captions'] = isset( $screenshots[1] ) && 5 === preg_match_all( '/^[0-9]+\. .+$/m', $screenshots[1] );
$checks['initial release changelog'] = false !== strpos( $readme, "= 1.0.0 =\n\n* Initial release." ) || false !== strpos( $readme, "= 1.0.0 =\n* Initial release." );
$pot = $zip->getFromName( $prefix . 'languages/' . $slug . '.pot' );
$checks['catalog domain and public name'] = false !== strpos( $pot, 'X-Domain: ' . $slug )
	&& false !== strpos( $pot, 'Project-Id-Version: Logical Address Autocomplete for Formidable Forms' );
$checks['old catalogs removed'] = ! in_array( $prefix . 'languages/address-autocomplete-for-formidable-forms.pot', $files, true )
	&& ! in_array( $prefix . 'languages/wpgeo-address-autocomplete-for-formidable-forms.pot', $files, true );
$checks['old entry filenames removed'] = ! in_array( $prefix . 'address-autocomplete-for-formidable-forms.php', $files, true )
	&& ! in_array( $prefix . 'wpgeo-address-autocomplete-for-formidable-forms.php', $files, true );
$checks['all PHP translation domains renamed'] = true;
foreach ( $files as $file ) {
	if ( '.php' === substr( $file, -4 ) && preg_match( "/'(?:wpgeo-)?address-autocomplete-for-formidable-forms'/", $zip->getFromName( $file ) ) ) {
		$checks['all PHP translation domains renamed'] = false;
	}
}
$npm = json_decode( file_get_contents( $root . '/package.json' ), true );
$lock = json_decode( file_get_contents( $root . '/package-lock.json' ), true );
$checks['npm identity and lock agree'] = $slug === $npm['name'] && $npm['name'] === $lock['name'] && $lock['name'] === $lock['packages']['']['name'];
$zip->close();
$checksum = hash_file( 'sha256', $messages[0] );
exec( $command . ' 2>&1', $retry_messages, $retry_status );
$checks['existing artifacts are not overwritten'] = 0 !== $retry_status && $checksum === hash_file( 'sha256', $messages[0] );
echo json_encode( $checks, JSON_PRETTY_PRINT ) . PHP_EOL;
echo 'Test artifact: ' . $messages[0] . PHP_EOL;
exit( in_array( false, $checks, true ) ? 1 : 0 );
